-- Hand-written: settle-08c T4: a credit note, a debit note and an invoice for a payment received are issued with the signature, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `documents_signature_required` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND (NEW.type IN ('credit_note', 'debit_note') OR (NEW.type IN ('tax_invoice', 'export_invoice') AND json_type(NEW.header_extras, '$.advance') IS NOT NULL)) AND NOT (json_extract(NEW.issuer, '$.signature.sha256') IS NOT NULL AND json_type(NEW.issuer, '$.signatory') IS NULL) BEGIN SELECT RAISE(ABORT, 'documents_signature_required: a credit note, a debit note or an invoice for a payment received is issued with the signature'); END;
